def escape_html(value) -> str:
    return (
        str(
            value
            if value is not None
            else ""
        )
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#039;")
    )


def safe_int(
    value,
    default=0,
    minimum=0,
    maximum=None,
):
    try:
        number = int(value)
    except Exception:
        number = default

    if number < minimum:
        number = minimum

    if maximum is not None and number > maximum:
        number = maximum

    return number


def safe_float(
    value,
    default=0.0,
    minimum=0.0,
):
    try:
        number = float(value)
    except Exception:
        number = default

    return max(
        minimum,
        number,
    )


def generate_uuid():
    value = secrets.token_hex(16)

    return (
        f"{value[:8]}-"
        f"{value[8:12]}-"
        f"{value[12:16]}-"
        f"{value[16:20]}-"
        f"{value[20:32]}"
    )


def random_config_name(existing=None):
    existing = existing or set()
    alphabet = string.ascii_lowercase + string.digits
    for _ in range(80):
        length = secrets.randbelow(6) + 8
        name = "".join(secrets.choice(alphabet) for _ in range(length))
        if name not in existing and name and not name[0].isdigit():
            return name
    return secrets.token_hex(6)

def sanitize_config_name(name: str) -> str:
    if not name:
        return random_config_name()
    # Keep the project/config separator so generated names remain readable.
    cleaned = "".join(
        ch for ch in str(name)
        if ch.isascii() and (ch.isalnum() or ch in "-_" )
    ).strip("-_ ")
    if not cleaned:
        return random_config_name()
    if cleaned[0].isdigit():
        cleaned = "a" + cleaned
    return cleaned[:40]

def auto_config_name() -> str:
    return random_config_name()


def project_config_name(existing=None) -> str:
    """Generate a unique config remark/name with the project prefix first."""
    existing = existing or set()
    for _ in range(80):
        name = f"{APP_NAME}-{random_config_name()}"
        if name not in existing:
            return name
    return f"{APP_NAME}-{secrets.token_hex(6)}"


def now_ir():
    if IRAN_TZ:
        return datetime.now(IRAN_TZ)

    return datetime.now()


def uptime():
    seconds = int(
        time.time()
        - stats["start_time"]
    )

    h = seconds // 3600

    m = (
        seconds
        % 3600
    ) // 60

    s = (
        seconds
        % 60
    )

    return (
        f"{h:02d}:"
        f"{m:02d}:"
        f"{s:02d}"
    )


def fmt_bytes(value: int):
    value = int(
        value or 0
    )

    if value < 1024:
        return f"{value} B"

    if value < 1024 ** 2:
        return (
            f"{value / 1024:.1f} KB"
        )

    if value < 1024 ** 3:
        return (
            f"{value / 1024 ** 2:.2f} MB"
        )

    return (
        f"{value / 1024 ** 3:.2f} GB"
    )


def parse_size_to_bytes(
    value: float,
    unit: str,
):
    if value <= 0:
        return 0

    unit = (
        unit
        or "GB"
    ).upper()

    if unit == "TB":
        return int(
            value
            * 1024 ** 4
        )

    if unit == "GB":
        return int(
            value
            * 1024 ** 3
        )

    if unit == "MB":
        return int(
            value
            * 1024 ** 2
        )

    if unit == "KB":
        return int(
            value
            * 1024
        )

    return int(value)


def parse_speed_to_bytes(
    value: float,
    unit: str,
):
    if value <= 0:
        return 0

    unit = (
        unit
        or "MBIT"
    ).upper()

    if unit == "MBIT":
        return int(
            value
            * 1024
            * 1024
            / 8
        )

    if unit == "KB":
        return int(
            value * 1024
        )

    if unit == "MB":
        return int(
            value
            * 1024
            * 1024
        )

    return int(value)


def is_link_expired(
    link: dict,
):
    expiry = link.get(
        "expires_at"
    )

    if not expiry:
        return False

    try:
        return (
            datetime.now()
            > datetime.fromisoformat(
                expiry
            )
        )

    except Exception:
        return False


def is_link_allowed(
    link: dict | None,
):
    if link is None:
        return False

    if not link.get(
        "active",
        True,
    ):
        return False

    if is_link_expired(link):
        return False

    limit = int(
        link.get(
            "limit_bytes",
            0,
        )
        or 0
    )

    used = int(
        link.get(
            "used_bytes",
            0,
        )
        or 0
    )

    if (
        limit > 0
        and used >= limit
    ):
        return False

    return True


def unique_ips_for_uuid(
    uuid: str,
):
    return {
        connection.get("ip")
        for connection in connections.values()
        if connection.get("uuid") == uuid
        and connection.get("ip")
    }


def _is_cloudflare_edge_ip(value: str) -> bool:
    """Recognize Cloudflare edge addresses left by an earlier Edge session."""
    try:
        addr = ipaddress.ip_address(str(value or "").strip())
    except ValueError:
        return False
    return any(addr in ipaddress.ip_network(cidr) for cidr in (
        "173.245.48.0/20", "103.21.244.0/22", "103.22.200.0/22",
        "103.31.4.0/22", "141.101.64.0/18", "108.162.192.0/18",
        "190.93.240.0/20", "188.114.96.0/20", "197.234.240.0/22",
        "198.41.128.0/17", "162.158.0.0/15", "104.16.0.0/13",
        "104.24.0.0/14", "172.64.0.0/13", "131.0.72.0/22",
    ))


def _trusted_proxy(request: Request) -> bool:
    # Never trust spoofable forwarding headers unless the deployment opts in.
    if os.environ.get("ONEX_TRUST_PROXY", "0").strip().lower() not in {"1", "true", "yes"}:
        return False
    peer = request.client.host if request.client else ""
    raw = os.environ.get("ONEX_TRUSTED_PROXIES", "").strip()
    if not raw:
        return True
    try:
        addr = ipaddress.ip_address(peer)
        return any(addr in ipaddress.ip_network(item.strip(), strict=False) for item in raw.split(",") if item.strip())
    except ValueError:
        return False


def client_ip(request: Request):
    if _trusted_proxy(request):
        forwarded = request.headers.get("x-forwarded-for", "")
        if forwarded:
            # The left-most value is the client only after a trusted proxy verified the chain.
            return forwarded.split(",")[0].strip()
        real = request.headers.get("x-real-ip", "")
        if real:
            return real.strip()
    return request.client.host if request.client else "unknown"


def is_ip_allowed(
    link: dict | None,
    uuid: str,
    ip: str,
):
    if link is None:
        return False

    limit = int(
        link.get(
            "ip_limit",
            0,
        )
        or 0
    )

    if limit <= 0:
        return True

    ips = unique_ips_for_uuid(uuid)

    if ip in ips:
        return True

    # Edge -> direct handoff: the old Worker connections are transient runtime
    # state, not real devices. Remove only known Cloudflare-edge sessions for
    # this UUID before evaluating the saved IP limit.
    if not _is_cloudflare_edge_ip(ip):
        stale_edge_ids = [cid for cid, conn in connections.items()
                          if conn.get("uuid") == uuid and _is_cloudflare_edge_ip(conn.get("ip"))]
        for cid in stale_edge_ids:
            connections.pop(cid, None)
        if stale_edge_ids:
            ips = unique_ips_for_uuid(uuid)
            if ip in ips:
                return True

    # Do not let disconnected/stale in-memory sessions permanently consume the
    # limit. This table is runtime-only and is cleared on restart.
    if len(ips) >= limit and connections:
        now = time.time()
        recent = False
        for connection in connections.values():
            if connection.get("uuid") != uuid:
                continue
            try:
                age = now - datetime.fromisoformat(str(connection.get("connected_at"))).timestamp()
            except Exception:
                age = 0
            if age < 90:
                recent = True
                break
        if not recent:
            return True

    return len(ips) < limit


def get_host(
    request: Request | None = None,
) -> str:
    # Explicit deployment values win; request headers are only a fallback.
    candidates = public_endpoint_candidates()
    if request is not None:
        if _trusted_proxy(request):
            candidates.append(request.headers.get("x-forwarded-host", ""))
        candidates.append(request.headers.get("host", ""))
    for raw in candidates:
        value = str(raw or "").strip().strip("'\"")
        if "://" in value:
            value = value.split("://", 1)[1]
        value = value.split("/", 1)[0].split(",", 1)[0].strip()
        host = value.rsplit(":", 1)[0] if value.count(":") == 1 else value.strip("[]")
        if host and host.lower() not in {"localhost", "127.0.0.1", "0.0.0.0"}:
            CONFIG["host"] = host
            return host
    return CONFIG["host"]


# ============================================================
# PASSWORD
# ============================================================

def hash_password(password: str) -> str:
    """Hash with scrypt; the prefix makes migration and verification explicit."""
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(str(password).encode("utf-8"), salt=salt, n=2**14, r=8, p=1, dklen=32)
    return "scrypt$16384$8$1$" + salt.hex() + "$" + digest.hex()


def _legacy_hash_password(password: str) -> str:
    return hashlib.sha256((str(password) + SECRET_KEY).encode("utf-8")).hexdigest()


def verify_password(password: str, stored: str) -> bool:
    stored = str(stored or "")
    try:
        if stored.startswith("scrypt$"):
            _, n, r, p, salt_hex, digest_hex = stored.split("$", 5)
            actual = hashlib.scrypt(str(password).encode("utf-8"), salt=bytes.fromhex(salt_hex), n=int(n), r=int(r), p=int(p), dklen=len(bytes.fromhex(digest_hex)))
            return hmac.compare_digest(actual, bytes.fromhex(digest_hex))
        # One-way compatibility for existing installations. Successful login is migrated.
        return hmac.compare_digest(_legacy_hash_password(password), stored)
    except (ValueError, TypeError):
        return False


def password_needs_upgrade(stored: str) -> bool:
    return not str(stored or "").startswith("scrypt$")


def upgrade_password_if_needed(record: dict, password: str) -> None:
    stored = str(record.get("password_hash") or "")
    if password_needs_upgrade(stored) and verify_password(password, stored):
        record["password_hash"] = hash_password(password)


# ONEX default owner credentials.
# First deployment starts with username=admin / password=admin.
# After the owner changes credentials from Settings, the saved values are used.
_env_pw = os.environ.get("ADMIN_PASSWORD", "").strip()
_env_user = os.environ.get("ADMIN_USERNAME", "admin").strip().lower() or "admin"
AUTH = {
    "username": _env_user,
    "password_hash": hash_password(_env_pw or "admin"),
    "password_configured": True,
    "credentials_version": 1,
}

# Sub-admin accounts (panel operators with granular permissions)
ADMIN_ACCOUNTS: dict = {}
# session_token -> {"role": "owner"|"admin", "admin_id": str|None, "username": str}
SESSION_META: dict = {}

ALL_PERMS = (
    "dash", "configs", "create", "stats", "logs",
    "settings", "support", "telegram", "news", "admins",
)
DEFAULT_PERMS = {p: True for p in ALL_PERMS}


def default_admin_record(username: str, password: str, **kwargs) -> dict:
    return {
        "id": secrets.token_hex(8),
        "username": username.strip().lower(),
        "password_hash": hash_password(password),
        "label": kwargs.get("label") or username,
        "limit_bytes": int(kwargs.get("limit_bytes") or 0),
        "used_bytes": 0,
        "expires_at": kwargs.get("expires_at"),
        "active": True,
        "blocked": False,
        "permissions": {**DEFAULT_PERMS, **(kwargs.get("permissions") or {})},
        "created_at": datetime.now().isoformat(),
    }


def find_admin_by_username(username: str):
    u = (username or "").strip().lower()
    for aid, a in ADMIN_ACCOUNTS.items():
        if a.get("username") == u:
            return aid, a
    return None, None


def admin_is_valid(admin: dict) -> bool:
    if not admin or admin.get("blocked") or not admin.get("active", True):
        return False
    exp = admin.get("expires_at")
    if exp:
        try:
            if datetime.now() > datetime.fromisoformat(str(exp)):
                return False
        except Exception:
            pass
    limit = int(admin.get("limit_bytes") or 0)
    used = int(admin.get("used_bytes") or 0)
    if limit > 0 and used >= limit:
        return False
    return True



# ============================================================
# LOGIN BRUTE-FORCE PROTECTION
# ============================================================
# Maximum failed login attempts per IP inside the rolling window.
LOGIN_MAX_ATTEMPTS = 5
LOGIN_WINDOW_SECONDS = 15 * 60
LOGIN_LOCKOUT_SECONDS = 30 * 60  # 30 minutes lockout
LOGIN_MIN_PASSWORD_LENGTH = 6

LOGIN_FAILURES = defaultdict(deque)
LOGIN_LOCKED_UNTIL = {}


def _cleanup_login_state(ip: str, now: float | None = None):
    now = now if now is not None else time.time()

    locked_until = LOGIN_LOCKED_UNTIL.get(ip, 0)
    if locked_until and locked_until <= now:
        LOGIN_LOCKED_UNTIL.pop(ip, None)

    failures = LOGIN_FAILURES.get(ip)
    if not failures:
        return

    cutoff = now - LOGIN_WINDOW_SECONDS
    while failures and failures[0] <= cutoff:
        failures.popleft()

    if not failures:
        LOGIN_FAILURES.pop(ip, None)


def login_is_blocked(ip: str):
    now = time.time()
    _cleanup_login_state(ip, now)

    locked_until = LOGIN_LOCKED_UNTIL.get(ip, 0)
    if locked_until > now:
        return True, max(1, int(locked_until - now))

    return False, 0


def register_login_failure(ip: str):
    now = time.time()
    _cleanup_login_state(ip, now)

    failures = LOGIN_FAILURES.setdefault(ip, deque())
    failures.append(now)

    if len(failures) >= LOGIN_MAX_ATTEMPTS:
        LOGIN_LOCKED_UNTIL[ip] = now + LOGIN_LOCKOUT_SECONDS
        failures.clear()
        log_activity(
            "auth",
            f"IP به دلیل تلاش‌های متعدد ورود ناموفق به مدت {LOGIN_LOCKOUT_SECONDS // 60} دقیقه مسدود شد: {ip}",
            "err",
        )
        return True, LOGIN_LOCKOUT_SECONDS

    return False, max(0, LOGIN_MAX_ATTEMPTS - len(failures))


def clear_login_failures(ip: str):
    LOGIN_FAILURES.pop(ip, None)
    LOGIN_LOCKED_UNTIL.pop(ip, None)


# ============================================================
# SESSION
# ============================================================

SESSION_COOKIE = "pixonpanel_session"

# Public panel sessions expire; users can log in again.
SESSION_TTL = 60 * 60 * 24 * 7


async def create_session(meta: dict | None = None) -> str:

    token = secrets.token_urlsafe(48)

    async with SESSIONS_LOCK:
        SESSIONS[token] = (
            time.time()
            + SESSION_TTL
        )
        SESSION_META[token] = meta or {"role": "owner", "admin_id": None, "username": "owner"}

    return token


async def is_valid_session(
    token: str | None,
) -> bool:

    if not token:
        return False

    async with SESSIONS_LOCK:

        expiry = SESSIONS.get(token)

        if expiry is None:
            return False

        if expiry < time.time():

            SESSIONS.pop(
                token,
                None,
            )

            return False

        return True


async def destroy_session(
    token: str | None,
):
    if not token:
        return

    async with SESSIONS_LOCK:
        SESSIONS.pop(
            token,
            None,
        )
        SESSION_META.pop(token, None)


def get_session_meta(token: str | None) -> dict:
    if not token:
        return {"role": "owner", "admin_id": None, "username": "owner", "permissions": {p: True for p in ALL_PERMS}}
    meta = dict(SESSION_META.get(token) or {"role": "owner", "admin_id": None, "username": "owner"})
    if meta.get("role") == "owner":
        meta["permissions"] = {p: True for p in ALL_PERMS}
    else:
        aid = meta.get("admin_id")
        admin = ADMIN_ACCOUNTS.get(aid or "") or {}
        meta["permissions"] = {p: bool((admin.get("permissions") or {}).get(p, False)) for p in ALL_PERMS}
        meta["blocked"] = bool(admin.get("blocked"))
    return meta


def require_perm(perm: str):
    async def _dep(request: Request, token=Depends(require_auth)):
        meta = get_session_meta(token)
        if meta.get("role") == "owner":
            return token
        if not (meta.get("permissions") or {}).get(perm):
            raise HTTPException(status_code=403, detail="دسترسی به این بخش مجاز نیست")
        return token
    return _dep


async def require_auth(
    request: Request,
):
    token = request.cookies.get(
        SESSION_COOKIE
    )

    if not await is_valid_session(
        token
    ):
        raise HTTPException(
            status_code=401,
            detail="unauthorized",
        )

    meta = get_session_meta(token)
    if meta.get("role") == "admin":
        aid = meta.get("admin_id")
        admin = ADMIN_ACCOUNTS.get(aid or "")
        if not admin_is_valid(admin or {}):
            await destroy_session(token)
            raise HTTPException(status_code=401, detail="حساب منقضی یا مسدود شده است")

    return token


def set_auth_cookie(
    response,
    request: Request,
    token: str,
):
    forwarded_proto = (
        request.headers
        .get(
            "x-forwarded-proto",
            "",
        )
        .lower()
    )

    is_https = (
        forwarded_proto == "https"
        or request.url.scheme == "https"
    )

    response.set_cookie(
        key=SESSION_COOKIE,
        value=token,
        max_age=SESSION_TTL,
        httponly=True,
        samesite="lax",
        path="/",
        secure=is_https,
    )


# ============================================================
# VLESS LINK GENERATION
# ============================================================

# Native sing-box listener ports are shared by all accounts.  The panel
# stores credentials per UUID while the native core keeps one listener per
# protocol.  This is what makes the "all protocols" subscription a single
# account instead of creating unrelated accounts.
def protocol_public_port(link: dict | None, protocol: str, fallback: int = DEFAULT_PORT) -> int:
    if (link or {}).get("all_protocols") and protocol not in getattr(NATIVE_CORE, "SUPPORTED", ()):
        return safe_int((link or {}).get("port", fallback), fallback, MIN_PORT, MAX_PORT)
    if protocol in {"vless-ws", "xhttp-packet-up", "xhttp-stream-up", "xhttp-stream-one", "trojan-ws", "vmess-ws"}:
        return safe_int((link or {}).get("port", fallback), fallback, MIN_PORT, MAX_PORT)
    try:
        adv_ports = ((link or {}).get("advanced") or {}).get("ports") or []
        native_supported = list(getattr(NATIVE_CORE, "SUPPORTED", ()))
        if adv_ports and protocol in native_supported:
            if (link or {}).get("all_protocols"):
                try: idx = native_supported.index(protocol)
                except ValueError: idx = 0
                if idx < len(adv_ports):
                    return safe_int(adv_ports[idx], fallback, MIN_PORT, MAX_PORT)
            else:
                return safe_int(adv_ports[0], fallback, MIN_PORT, MAX_PORT)
        ports = NATIVE_CORE.public_ports()  # type: ignore[name-defined]
        return safe_int(ports.get(protocol, fallback), fallback, MIN_PORT, MAX_PORT)
    except Exception:
        return safe_int((link or {}).get("port", fallback), fallback, MIN_PORT, MAX_PORT)

def _ip_front_host(panel_host: str) -> str:
    """SNI/Host for IP-paired configs: the Cloudflare Worker domain when deployed, else the panel host."""
    try:
        from onex.integrations import cf_edge as _cf
        return _cf.edge_host(_cf.load()) or panel_host
    except Exception:
        return panel_host


def _generate_vless_link_base(
    uuid: str, host: str, remark: str = "ONEX",
    protocol: str = DEFAULT_PROTOCOL, fingerprint: str | None = None,
    alpn: str | None = None, port: int | None = None, link: dict | None = None,
    front_host: str = "",
):
    protocol = normalize_protocol(protocol)
    fp = (fingerprint or DEFAULT_FINGERPRINT).strip().lower()
    if fp not in FINGERPRINTS: fp = DEFAULT_FINGERPRINT
    port_value = protocol_public_port(link, protocol, safe_int(port, DEFAULT_PORT, MIN_PORT, MAX_PORT))
    alpn_value = (alpn or DEFAULT_ALPN_BY_PROTOCOL.get(protocol, "http/1.1")).strip()
    label = quote(str(remark or "ONEX"), safe="")
    adv = normalize_advanced_config((link or {}).get("advanced"))
    if link and link.get("all_protocols"):
        adv = _protocol_safe_advanced(adv, protocol, all_protocols=True)
    _front = front_host or host
    adv_host = adv["host"].get("host") or adv["host"].get("address") or _front
    adv_path = adv["host"].get("path") or adv["network"].get("path")
    adv_sni = adv["tls"].get("sni") or adv["tls"].get("server_name") or _front
    adv_fp = adv["fingerprint"].get("value") or fp
    adv_alpn = adv["tls"].get("alpn") or alpn_value
    security = adv["tls"].get("mode") if adv["tls"].get("enabled", True) else "none"
    if security not in {"none","tls","reality"}: security = "tls"
    # All-protocol subscriptions share one account but not one wire schema.
    if protocol in {"shadowsocks", "socks5"}:
        security = "none"
    elif protocol in {"http", "hysteria2"} and security == "reality":
        security = "tls"
    elif protocol == "trojan" and security == "none":
        security = "tls"
    elif protocol == "vless-grpc-reality":
        security = "reality"
    if protocol == "vless-ws":
        path = adv_path or f"/ws/{uuid}"
        q = {"encryption":"none","security":security,"type":"ws","host":adv_host,"path":path,"sni":adv_sni,"fp":adv_fp,"alpn":adv_alpn}
        if adv["tls"].get("allow_insecure"): q["allowInsecure"] = "1"
        if security == "reality":
            r=adv["tls"]["reality"]
            if r.get("public_key"): q["pbk"]=r["public_key"]
            if r.get("short_id"): q["sid"]=r["short_id"]
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol.startswith("xhttp-"):
        mode = protocol.replace("xhttp-", "")
        # stream-one carries the VLESS UUID inside the request body, so its
        # HTTP path MUST NOT contain /{uuid}. packet-up/stream-up keep their
        # session-bearing paths unchanged.
        if mode == "stream-one":
            path = "/xhttp-siz10/stream-one/"
        else:
            path = adv_path or f"/xhttp-siz10/{mode}/{uuid}"
        q = {"encryption":"none","security":security,"type":"xhttp","mode":mode,"host":adv_host,"path":path,"sni":adv_sni,"fp":adv_fp,"alpn":adv_alpn}
        if adv["tls"].get("allow_insecure"): q["allowInsecure"] = "1"
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "siderail-vless-xhttp":
        # Exact SideRail shape: no mode param (client uses auto), core path.
        path = adv_path or "/siderail/xhttp"
        q = {"encryption":"none","security":security,"type":"xhttp","host":adv_host,"path":path,"sni":adv_sni,"fp":adv_fp,"alpn":"h2,http/1.1"}
        if adv["tls"].get("allow_insecure"): q["allowInsecure"] = "1"
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "vless-httpupgrade":
        # Real HTTPUpgrade relay on the front proxy; uuid in path for quota/auth.
        path = adv_path or f"/httpup/{uuid}"
        q = {"encryption":"none","security":security,"type":"httpupgrade","host":adv_host,"path":path,"sni":adv_sni,"fp":adv_fp,"alpn":adv_alpn}
        if adv["tls"].get("allow_insecure"): q["allowInsecure"] = "1"
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "vmess-ws":
        # Exact SideRail VMess-WS shape; traffic is piped to the local sing-box
        # VMess listener which owns the VMess handshake (alterId 0 / AEAD).
        raw = {"v":"2","ps":remark,"add":host,"port":port_value,"id":uuid,"aid":0,"scy":"auto","net":"ws","type":"none","host":host,"path":"/siderail/vmess","tls":"tls","sni":host,"alpn":"http/1.1","fp":fp}
        return "vmess://" + base64.b64encode(json.dumps(raw,separators=(",",":"),ensure_ascii=False).encode()).decode()
    if protocol == "trojan-ws":
        # Keep Trojan+WS client transport settings aligned with VLESS+WS.
        # The password remains the UUID; the WS/TLS transport follows the
        # same advanced host/path/SNI/fingerprint/ALPN settings.
        path = adv_path or f"/ws/{uuid}"
        q = {
            "security": security,
            "type": "ws",
            "host": adv_host,
            "path": path,
            "sni": adv_sni,
            "fp": adv_fp,
            "alpn": adv_alpn,
        }
        if adv["tls"].get("allow_insecure"):
            q["allowInsecure"] = "1"
        return "trojan://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "trojan":
        mode = security if security in {"tls", "none"} else "tls"
        q = {"security": mode, "sni": adv_sni}
        if adv_alpn: q["alpn"] = adv_alpn
        if adv["tls"].get("allow_insecure") or getattr(NATIVE_CORE, "self_signed", False): q["allowInsecure"] = "1"
        net = str(adv["network"].get("type") or "tcp")
        if net != "tcp":
            q["type"] = net
            if adv_path: q["path"] = adv_path
            if adv_host: q["host"] = adv_host
            if adv["host"].get("service_name"): q["serviceName"] = adv["host"]["service_name"]
        return f"trojan://{uuid}@{host}:{port_value}?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "vless-grpc-reality":
        try:
            reality = NATIVE_CORE.reality_info()  # type: ignore[name-defined]
            custom_r = adv["tls"].get("reality") or {}
            pbk = quote(str(custom_r.get("public_key") or reality.get("public_key", "")), safe="")
            sid = quote(str(custom_r.get("short_id") or reality.get("short_id", "")), safe="")
        except Exception:
            pbk, sid = "", ""
        service_name = adv["host"].get("service_name") or adv["network"].get("service_name") or "ONEX"
        q = {"encryption":"none","security":"reality","type":"grpc","serviceName":service_name,"sni":adv_sni,"fp":adv_fp,"pbk":pbk,"sid":sid}
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/')}" for k,v in q.items()) + "#" + label
    if protocol == "shadowsocks":
        method = str((adv.get("shadowsocks") or {}).get("method") or os.getenv("ONEX_SS_METHOD", "aes-256-gcm"))
        userinfo = base64.urlsafe_b64encode(f"{method}:{uuid}".encode()).decode().rstrip("=")
        return f"ss://{userinfo}@{host}:{port_value}#{label}"
    if protocol == "socks5": return f"socks5://{uuid}:{uuid}@{host}:{port_value}#{label}"
    if protocol == "http":
        scheme = "https" if security == "tls" else "http"
        extra = f"?sni={quote(adv_sni)}" if scheme == "https" else ""
        return f"{scheme}://{uuid}:{uuid}@{host}:{port_value}{extra}#{label}"
    if protocol == "hysteria2":
        insecure = 1 if (adv["tls"].get("allow_insecure") or getattr(NATIVE_CORE, "self_signed", False)) else 0
        q = {"sni": adv_sni, "insecure": insecure}
        hy = adv.get("hysteria2") or {}
        if hy.get("obfs_password"): q["obfs"] = hy.get("obfs_type") or "salamander"; q["obfs-password"] = hy.get("obfs_password")
        return f"hysteria2://{uuid}@{host}:{port_value}/?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "vless-reality":
        try:
            reality = NATIVE_CORE.reality_info()  # type: ignore[name-defined]
            custom_r = adv["tls"].get("reality") or {}
            pbk = quote(str(custom_r.get("public_key") or reality.get("public_key", "")), safe="")
            sid = quote(str(custom_r.get("short_id") or reality.get("short_id", "")), safe="")
        except Exception:
            pbk, sid = "", ""
        q = {"encryption":"none","security":"reality","type":"tcp","sni":adv_sni,"fp":adv_fp,"pbk":pbk,"sid":sid}
        return "vless://" + uuid + "@" + host + ":" + str(port_value) + "?" + "&".join(f"{k}={quote(str(v), safe=',/') }" for k,v in q.items()) + "#" + label
    if protocol == "vmess":
        raw = {"v":"2","ps":remark,"add":host,"port":port_value,"id":uuid,"aid":0,"scy":"auto","net":"tcp","type":"none","host":"","path":"","tls":"tls","sni":adv_sni,"fp":adv_fp}
        return "vmess://" + base64.b64encode(json.dumps(raw,separators=(",",":"),ensure_ascii=False).encode()).decode()
    if protocol == "tuic":
        return f"tuic://{uuid}:{uuid}@{host}:{port_value}?sni={quote(adv_sni)}&alpn=h3&congestion_control=bbr#" + label
    if protocol == "anytls":
        insecure = 1 if (adv["tls"].get("allow_insecure") or getattr(NATIVE_CORE, "self_signed", False)) else 0
        return f"anytls://{uuid}@{host}:{port_value}?sni={quote(adv_sni)}&insecure={insecure}#" + label
    if protocol == "naive":
        return f"naive+https://{quote(uuid)}:{quote(uuid)}@{host}:{port_value}/?sni={quote(adv_sni)}#" + label
    if protocol == "shadowtls":
        hs = quote(str(os.getenv("ONEX_SHADOWTLS_HANDSHAKE", adv_sni or host)))
        return f"shadowtls://{uuid}@{host}:{port_value}?version=3&sni={hs}#" + label
    if protocol == "snell":
        return f"snell://{uuid}@{host}:{port_value}?version=5#" + label
    if protocol == "hysteria":
        insecure = 1 if (adv["tls"].get("allow_insecure") or getattr(NATIVE_CORE, "self_signed", False)) else 0
        return f"hysteria://{uuid}@{host}:{port_value}/?sni={quote(adv_sni)}&insecure={insecure}#" + label
    if protocol == "tuic": return f"tuic://{uuid}:{uuid}@{host}:{port_value}?sni={quote(host)}&alpn=h3#{label}"
    return f"vless://{uuid}@{host}:{port_value}"


# ============================================================
# CONFIG OPTIMIZER (cs + fm) for VLESS / Trojan
# ============================================================
CDN_OPT_CIPHER_SUITES = (
    "TLS_AES_256_GCM_SHA384:TLS_CHACHA20_POLY1305_SHA256:TLS_AES_128_GCM_SHA256:"
    "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384:TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384:"
    "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256:TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256:"
    "TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256:TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256:"
    "TLS_ECDHE_ECDSA_WITH_AES_256_CBC_SHA:TLS_ECDHE_RSA_WITH_AES_256_CBC_SHA:"
    "TLS_ECDHE_ECDSA_WITH_AES_128_CBC_SHA256:TLS_ECDHE_RSA_WITH_AES_128_CBC_SHA256"
)
CDN_OPT_FINAL_MASK = json.dumps({
    "tcp": [
        {"type": "fragment", "settings": {"packets": "tlshello", "lengths": ["0", "104", "1"], "delays": ["0"], "maxSplit": "0"}},
        {"type": "fragment", "settings": {"packets": "1-1", "lengths": ["114", "1"], "delays": ["1"], "maxSplit": "11"}},
    ]
}, separators=(",", ":"))
CDN_OPT_DEFAULT_ECH = "cloudflare-ech.com+udp://1.1.1.1"
_CDN_ECH_RE = re.compile(r"^[A-Za-z0-9.\-]{1,190}(\+(udp|tcp|https?)://[A-Za-z0-9.\-:\[\]/]{1,120})?$")


def normalize_cdn_ech(value) -> str:
    """Accept one ECH value like 'cloudflare-ech.com+udp://1.1.1.1'; empty disables ECH."""
    v = str(value or "").strip()
    if not v:
        return ""
    return v if _CDN_ECH_RE.match(v) else ""


def apply_cdn_optimizer(uri: str, link: dict | None) -> str:
    """Add cs (Cipher Suites) + fm (FinalMask) to a vless:// or trojan:// URI.

    Only those parameters are replaced; host, port, path, sni, remark and every
    other parameter are kept exactly as generated. Other protocols pass through.
    """
    if not link or not link.get("cdn_optimizer") or not isinstance(uri, str):
        return uri
    if not (link.get("bundle_protocols") or link.get("all_protocols")):
        return uri  # only ONEX VIP (multi-protocol) configs
    low = uri[:10].lower()
    if not (low.startswith("vless://") or low.startswith("trojan://")):
        return uri
    base, sep, frag = uri.partition("#")
    head, qsep, query = base.partition("?")
    pairs = []
    security = ""
    for part in (query.split("&") if query else []):
        if not part:
            continue
        key = part.split("=", 1)[0]
        if key in ("cs", "fm"):
            continue
        if key == "security":
            security = unquote(part.split("=", 1)[1] if "=" in part else "").lower()
        pairs.append(part)
    extra = [
        "cs=" + quote(CDN_OPT_CIPHER_SUITES, safe=""),
        "fm=" + quote(CDN_OPT_FINAL_MASK, safe=""),
    ]
    out = head + "?" + "&".join(extra + pairs)
    return out + (sep + frag if sep else "")


def _apply_cdn_ech_vmess(uri: str, ech: str) -> str:
    """VMess links are base64 JSON: store the ECH value as an extra "ech" key."""
    try:
        raw_b64 = uri[len("vmess://"):].strip()
        data = json.loads(base64.b64decode(raw_b64 + "=" * (-len(raw_b64) % 4)).decode("utf-8"))
    except Exception:
        return uri
    if not isinstance(data, dict):
        return uri
    data["ech"] = ech
    return "vmess://" + base64.b64encode(json.dumps(data, separators=(",", ":"), ensure_ascii=False).encode()).decode()


def apply_cdn_ech(uri: str, link: dict | None) -> str:
    """Add the Cloudflare ECH value (ech=...) to a vless:// or trojan:// URI when the link has one."""
    ech = normalize_cdn_ech((link or {}).get("cdn_ech"))
    if not ech or not isinstance(uri, str):
        return uri
    low = uri[:10].lower()
    if low.startswith("vmess://"):
        return _apply_cdn_ech_vmess(uri, ech)
    if not (low.startswith("vless://") or low.startswith("trojan://")):
        return uri
    base, sep, frag = uri.partition("#")
    head, qsep, query = base.partition("?")
    pairs = [p for p in (query.split("&") if query else []) if p and p.split("=", 1)[0] != "ech"]
    out = head + "?" + "&".join(["ech=" + quote(ech, safe="")] + pairs)
    return out + (sep + frag if sep else "")


def generate_vless_link(*args, link: dict | None = None, **kwargs):
    return apply_cdn_ech(apply_cdn_optimizer(_generate_vless_link_base(*args, link=link, **kwargs), link), link)


def vless_link_for_link(
    link: dict,
    uid: str,
    host: str,
):
    return generate_vless_link(
        uid,
        host,
        remark=str(link.get("label") or "Config"),
        protocol=link.get(
            "protocol",
            DEFAULT_PROTOCOL,
        ),
        fingerprint=link.get(
            "fingerprint",
            DEFAULT_FINGERPRINT,
        ),
        alpn=link.get(
            "alpn"
        ),
        port=protocol_public_port(link, link.get("protocol", DEFAULT_PROTOCOL), link.get("port", DEFAULT_PORT)),
        link=link,
    )


def group_subscription_lines_for_link(
    link: dict, uid: str, host: str, protocols, used_names: set[str] | None = None,
):
    """Expand one group member into every protocol enabled for the group."""
    # A link has two distinct subscription modes:
    #   * all_protocols=True  -> emit every protocol enabled for the group
    #   * all_protocols=False -> emit ONLY the protocol explicitly selected
    #
    # Previously this function always used the group's protocol list, which
    # meant a normal single-protocol link could unexpectedly appear as every
    # protocol in its subscription.
    selected = [p for p in link_sub_protocols(link) if p in PROTOCOLS]
    if not selected:
        return []
    names = used_names if used_names is not None else set()
    cfg_count = 1 if (link.get("all_protocols") or link.get("bundle_protocols")) else max(1, min(40, int(link.get("config_count") or 1)))
    clean_ips = list(link.get("clean_ips") or [])
    if clean_ips:
        hosts = []
        while len(hosts) < cfg_count:
            hosts.extend(clean_ips)
        hosts = hosts[:cfg_count]
    else:
        hosts = [host] * cfg_count
    lines = []
    base_label = str(link.get("label") or "Config")
    for index, target_host in enumerate(hosts, 1):
        for proto in selected:
            remark = f"{PROTOCOL_SUB_ICONS.get(proto, '🔹')} {PROTOCOL_SUB_NAMES.get(proto) or PROTOCOL_LABELS.get(proto, proto)} | {base_label}"
            if cfg_count > 1:
                remark += f" #{index}"
            if remark in names:
                n = 2
                candidate = f"{remark} ({n})"
                while candidate in names:
                    n += 1
                    candidate = f"{remark} ({n})"
                remark = candidate
            names.add(remark)
            lines.append(generate_vless_link(
                uid, target_host, remark=remark, protocol=proto,
                fingerprint=link.get("fingerprint", DEFAULT_FINGERPRINT),
                alpn=DEFAULT_ALPN_BY_PROTOCOL.get(proto, link.get("alpn")),
                port=protocol_public_port(link, proto, link.get("port", DEFAULT_PORT)),
                link=link,
            ))
    return lines


def link_config_uris(link: dict, uid: str, host: str) -> list[str]:
    """Every real config URI of one link, exactly as its subscription emits them.

    Used by /sub/{uuid}, the dashboard copy boxes and the browser info page so
    all three always contain the very same full list (every selected protocol
    of the bundle, every clean IP / config copy).
    """
    link = link or {}
    clean_ips = list(link.get("clean_ips") or [])
    protocols = [p for p in link_sub_protocols(link) if p in PROTOCOLS] or [
        normalize_protocol(str(link.get("protocol", DEFAULT_PROTOCOL)))
    ]
    multi = bool(link.get("all_protocols") or link.get("bundle_protocols"))
    cfg_count = 1 if multi else max(1, min(40, int(link.get("config_count") or 1)))
    if clean_ips:
        hosts = list(clean_ips)
        while len(hosts) < cfg_count:
            hosts.extend(clean_ips)
        hosts = hosts[:max(cfg_count, len(clean_ips) if multi else cfg_count)]
    else:
        hosts = [host] * cfg_count
    pairs = link.get("ip_proto_pairs") or []
    if pairs:
        pair_names: set = set()
        pair_uris = []
        for idx, (target, proto) in enumerate(pairs, 1):
            name = subscription_config_name(link, proto, pair_names, idx)
            pair_uris.append(generate_vless_link(
                uid, (target or host), remark=name, protocol=proto, front_host=_ip_front_host(host),
                fingerprint=link.get("fingerprint", DEFAULT_FINGERPRINT),
                alpn=DEFAULT_ALPN_BY_PROTOCOL.get(proto, link.get("alpn")),
                port=protocol_public_port(link, proto, link.get("port", DEFAULT_PORT)),
                link=link,
            ))
        return pair_uris
    used_names: set = set()
    uris = []
    for idx, target in enumerate(hosts, 1):
        for proto in protocols:
            name = subscription_config_name(link, proto, used_names, idx if len(hosts) > 1 else 0)
            uris.append(generate_vless_link(
                uid, target, remark=name, protocol=proto,
                fingerprint=link.get("fingerprint", DEFAULT_FINGERPRINT),
                alpn=DEFAULT_ALPN_BY_PROTOCOL.get(proto, link.get("alpn")),
                port=protocol_public_port(link, proto, link.get("port", DEFAULT_PORT)),
                link=link,
            ))
    return uris


def get_link_info(
    link: dict,
    uid: str,
    host: str,
):
    connected_count = len(unique_ips_for_uuid(uid))
    is_active = is_link_allowed(link)
    limit_b = int(link.get("limit_bytes", 0) or 0)
    used_b = int(link.get("used_bytes", 0) or 0)
    is_expired = is_link_expired(link) or (limit_b > 0 and used_b >= limit_b)
    if not is_active or is_expired:
        status_color = "red"
    elif connected_count > 0:
        status_color = "green"
    else:
        status_color = "gray"
    clean_ips = link.get("clean_ips") or []
    cfg_count = int(link.get("config_count") or 1)
    show_vless = len(clean_ips) <= 1 and cfg_count <= 1
    cat = CATEGORIES.get(str(link.get("category_id") or "0")) or {}
    try:
        _all_uris = link_config_uris(link, uid, host)
    except Exception:
        _all_uris = [vless_link_for_link(link, uid, host)]
    return {
        "uuid": uid,
        "name": link.get("label", ""),
        "label": link.get("label", ""),
        "protocol": link.get("protocol", DEFAULT_PROTOCOL),
        "bundle_protocols": list(link.get("bundle_protocols") or []),
        "ad_block_enabled": bool(link.get("ad_block_enabled", AD_BLOCKER.get("enabled"))),
        "cdn_optimizer": bool(link.get("cdn_optimizer", False)),
        "cdn_ech": str(link.get("cdn_ech") or ""),
        "active": is_active,
        "used_bytes": used_b,
        "limit_bytes": limit_b,
        "expires_at": link.get("expires_at"),
        "ip_limit": int(link.get("ip_limit", 0) or 0),
        "speed_limit_bytes": int(link.get("speed_limit_bytes", 0) or 0),
        "connection_limit": int(link.get("connection_limit", 0) or 0),
        "fragment": link.get("fragment", "off"),
        "fingerprint": link.get("fingerprint", DEFAULT_FINGERPRINT),
        "alpn": link.get("alpn", ""),
        "port": link.get("port", DEFAULT_PORT),
        "note": link.get("note", ""),
        "clean_ips": clean_ips,
        "alarm_enabled": bool(link.get("alarm_enabled", False)),
        "category_id": str(link.get("category_id") or "0"),
        "sort_order": int(link.get("sort_order") or 0),
        "category_number": int(cat.get("number", 0)),
        "category_name": str(cat.get("name", "عمومی")),
        "sub_id": str(link.get("sub_id") or ""),
        "config_count": cfg_count,
        "status_color": status_color,
        "connected_ips": connected_count,
        "show_vless": show_vless,
        "vless": vless_link_for_link(link, uid, host) if show_vless else "",
        "vless_full": vless_link_for_link(link, uid, host),
        "vless_all": "\n".join(_all_uris),
        "configs_total": len(_all_uris),
        "sub_protocols": link_sub_protocols(link),
        "sub": f"https://{host}/sub/{uid}",
        "info": f"https://{host}/info/{uid}",
        "support": SUPPORT_USERNAME,
        "advanced": normalize_advanced_config(link.get("advanced")),
    }


# ============================================================
# PERSISTENCE
# ============================================================

async def load_state():

    global AUTH

    try:

        DATA_DIR.mkdir(
            parents=True,
            exist_ok=True,
        )

        if not DATA_FILE.exists():
            return

        async with aiofiles.open(
            DATA_FILE,
            "r",
            encoding="utf-8",
        ) as file:
            raw = await file.read()

        data = json.loads(raw)
        if isinstance(data.get("edge_scan_state"), dict):
            EDGE_SCAN_STATE.update(data["edge_scan_state"])

        LINKS.update(
            data.get(
                "links",
                {},
            )
        )

        SUBS.update(
            data.get(
                "subs",
                {},
            )
        )

        CATEGORIES.update(
            data.get(
                "categories",
                {},
            )
        )
        AD_BLOCKER.update(data.get("ad_blocker") or {})
        AD_BLOCKER["enabled"] = bool(AD_BLOCKER.get("enabled"))
        AD_BLOCKER["domains"] = sorted({
            normalize_block_domain(x)
            for x in (AD_BLOCKER.get("domains") or [])
            if normalize_block_domain(x)
        })

        ADMIN_ACCOUNTS.clear()
        ADMIN_ACCOUNTS.update(data.get("admin_accounts") or {})

        stored_password = data.get(
            "password_hash"
        )
        stored_username = str(data.get("username") or "").strip().lower()
        stored_cred_version = int(data.get("credentials_version") or 0)

        # One-time migration from the legacy setup screen.
        # Existing legacy credentials are intentionally replaced with admin/admin.
        if stored_cred_version < 1:
            AUTH["username"] = "admin"
            AUTH["password_hash"] = hash_password("admin")
            AUTH["password_configured"] = True
            AUTH["credentials_version"] = 1
            logger.info("Legacy credentials migrated to ONEX default admin/admin")
        else:
            if stored_username:
                AUTH["username"] = stored_username
            if stored_password:
                AUTH["password_hash"] = stored_password
            AUTH["password_configured"] = True
            AUTH["credentials_version"] = stored_cred_version

        # Remove the legacy automatically-created default config.
        await remove_legacy_default_links()

        # Compatibility for older records
        for uid, link in LINKS.items():

            link.setdefault(
                "protocol",
                DEFAULT_PROTOCOL,
            )

            link.setdefault(
                "fingerprint",
                DEFAULT_FINGERPRINT,
            )

            link.setdefault(
                "alpn",
                "",
            )

            link.setdefault(
                "port",
                DEFAULT_PORT,
            )

            link.setdefault(
                "ip_limit",
                0,
            )

            link.setdefault(
                "speed_limit_bytes",
                0,
            )

            link.setdefault(
                "connection_limit",
                0,
            )

            link.setdefault(
                "fragment",
                "off",
            )

            link.setdefault(
                "used_bytes",
                0,
            )
            link.setdefault("clean_ips", [])
            link.setdefault("alarm_enabled", False)
            link.setdefault("category_id", "0")
            link.setdefault("config_count", 1)
            link.setdefault("sort_order", 0)
            link.setdefault("usage_history", [])
            link.setdefault("bundle_protocols", [])
            if link.get("all_protocols"):
                # Upgrade old 3-protocol "all" links to the full ONEX VIP set.
                link["bundle_protocols"] = [p for p in RAILWAY_SUB_PROTOCOLS]
            link.setdefault("ad_block_enabled", False)
            link["advanced"] = normalize_advanced_config(link.get("advanced"))

        logger.info(
            "State loaded: %d links / %d subscriptions",
            len(LINKS),
            len(SUBS),
        )

    except Exception as exc:

        logger.exception(
            "Could not load state: %s",
            exc,
        )


async def save_state():

    async with SAVE_LOCK:

        try:

            DATA_DIR.mkdir(
                parents=True,
                exist_ok=True,
            )

            payload = {
                "links":
                    dict(LINKS),

                "subs":
                    dict(SUBS),

                "categories":
                    dict(CATEGORIES),

                "ad_blocker":
                    dict(AD_BLOCKER),

                "admin_accounts":
                    dict(ADMIN_ACCOUNTS),

                "username":
                    AUTH.get("username", "admin"),

                "password_hash":
                    AUTH[
                        "password_hash"
                    ],

                "credentials_version":
                    1,

                "saved_at":
                    datetime.now().isoformat(),
                "edge_scan_state": dict(EDGE_SCAN_STATE),
            }

            temp_file = (
                DATA_FILE.with_suffix(
                    ".tmp"
                )
            )

            async with aiofiles.open(
                temp_file,
                "w",
                encoding="utf-8",
            ) as file:

                await file.write(
                    json.dumps(
                        payload,
                        ensure_ascii=False,
                        indent=2,
                    )
                )

            temp_file.replace(
                DATA_FILE
            )

        except Exception as exc:

            logger.exception(
                "Could not save state: %s",
                exc,
            )


# ============================================================
# DEFAULT LINK
# ============================================================

async def ensure_default_categories():
    # گروه‌های پیش‌فرض ساخته نمی‌شوند — کاربر خودش می‌سازد
    return


async def remove_legacy_default_links():
    """Remove the old automatically-created default config from persisted state."""
    removed = []
    async with LINKS_LOCK:
        for uid, link in list(LINKS.items()):
            if link.get("is_default") or str(link.get("label") or "").strip() == "لینک پیش‌فرض":
                removed.append(uid)
                del LINKS[uid]
    if removed:
        logger.info("Removed %d legacy default link(s)", len(removed))


# ============================================================
# LINK MANAGEMENT
# ============================================================

async def make_link(
    label: str = "لینک جدید",
    limit_bytes: int = 0,
    expires_at: str | None = None,
    note: str = "",
    sub_id: str | None = None,
    protocol: str = DEFAULT_PROTOCOL,
    fingerprint: str = DEFAULT_FINGERPRINT,
    alpn: str = "",
    port: int = DEFAULT_PORT,
    ip_limit: int = 0,
    speed_limit_bytes: int = 0,
    connection_limit: int = 0,
    fragment: str = "off",
    clean_ips=None,
    alarm_enabled: bool = False,
    category_id: str = "0",
    config_count: int = 1,
    all_protocols: bool = False,
    bundle_protocols=None,
    ad_blocker: bool | None = None,
    advanced: dict | None = None,
    cdn_optimizer: bool = False,
    cdn_ech: str = "",
):

    if not PROTOCOLS:
        raise HTTPException(503, "No protocol backend is available")

    protocol = normalize_protocol(protocol)

    fingerprint = (
        fingerprint
        or DEFAULT_FINGERPRINT
    ).strip().lower()

    if fingerprint not in FINGERPRINTS:
        fingerprint = DEFAULT_FINGERPRINT

    if not (
        MIN_PORT
        <= port
        <= MAX_PORT
    ):
        port = DEFAULT_PORT

    uid = generate_uuid()

    clean_label = sanitize_config_name((label or "").strip() or random_config_name())
    project_prefix = f"{APP_NAME}-"
    if not clean_label.lower().startswith(project_prefix.lower()):
        clean_label = f"{project_prefix}{clean_label}"

    record = {
        "label":
            clean_label[:40],

        "limit_bytes":
            max(
                0,
                int(limit_bytes),
            ),

        "used_bytes":
            0,

        "created_at":
            datetime.now().isoformat(),

        "active":
            True,

        "expires_at":
            expires_at,

        "note":
            (
                note
                or ""
            ).strip()[:500],

        "sub_id":
            sub_id,

        "protocol":
            protocol,

        "fingerprint":
            fingerprint,

        "alpn":
            (
                alpn
                or ""
            ).strip()[:100],

        "port":
            port,

        "ip_limit":
            max(
                0,
                int(ip_limit),
            ),

        "speed_limit_bytes":
            max(
                0,
                int(speed_limit_bytes),
            ),

        "connection_limit":
            max(
                0,
                int(connection_limit),
            ),

        "fragment":
            (
                fragment
                or "off"
            ).strip().lower(),

        "security_profile": "balanced",
        "multi_login": False,
        "protocol_label": PROTOCOL_LABELS.get(protocol, protocol),
        "clean_ips": list(clean_ips or []),
        "alarm_enabled": bool(alarm_enabled),
        "category_id": str(category_id or "0"),
        "config_count": max(1, min(40, int(config_count or 1))),
        "all_protocols": bool(all_protocols),
        "bundle_protocols": [
            p for p in (bundle_protocols or [])
            if p in BUNDLE_PROTOCOLS
        ],
        "advanced": normalize_advanced_config(advanced),
        "native_protocols": [p for p in PROTOCOLS if p not in {"vless-ws", "xhttp-packet-up", "xhttp-stream-up", "xhttp-stream-one", "trojan-ws", "vmess-ws"}],
        "usage_history": [],
        "ad_block_enabled": bool(AD_BLOCKER.get("enabled") if ad_blocker is None else ad_blocker),
        "cdn_optimizer": bool(cdn_optimizer),
        "cdn_ech": normalize_cdn_ech(cdn_ech),
    }

    async with LINKS_LOCK:
        LINKS[uid] = record

    if sub_id:

        async with SUBS_LOCK:

            if sub_id in SUBS:

                ids = SUBS[
                    sub_id
                ].setdefault(
                    "link_ids",
                    [],
                )

                if uid not in ids:
                    ids.append(uid)

    await save_state()

    log_activity(
        "link",
        (
            f"کانفیگ "
            f"«{record['label']}» "
            f"ساخته شد"
        ),
        "ok",
    )

    return uid, record


async def remove_link(
    uid: str,
):

    async with LINKS_LOCK:

        if uid not in LINKS:
            return None

        label = LINKS[
            uid
        ].get(
            "label",
            uid,
        )

        sub_id = LINKS[
            uid
        ].get(
            "sub_id"
        )

        del LINKS[uid]

    if sub_id:

        async with SUBS_LOCK:

            if sub_id in SUBS:

                ids = SUBS[
                    sub_id
                ].get(
                    "link_ids",
                    [],
                )

                if uid in ids:
                    ids.remove(uid)

    await save_state()

    log_activity(
        "link",
        (
            f"کانفیگ "
            f"«{label}» "
            f"حذف شد"
        ),
        "warn",
    )

    return label


async def set_link_active(
    uid: str,
    active: bool,
):

    async with LINKS_LOCK:

        if uid not in LINKS:
            return None

        LINKS[
            uid
        ][
            "active"
        ] = bool(active)

        record = LINKS[uid]

    await save_state()
    if NATIVE_CORE and not await sync_native_core():
        async with LINKS_LOCK:
            LINKS[uid]["active"] = not bool(active)
        await save_state()
        raise HTTPException(409, NATIVE_CORE.last_error or "Native runtime reload failed; previous state restored")

    if SIDERAIL_CORE:
        asyncio.create_task(sync_siderail_core())

    log_activity(
        "link",
        (
            f"کانفیگ "
            f"«{record['label']}» "
            f"{'فعال' if active else 'غیرفعال'} شد"
        ),
        "ok"
        if active
        else "warn",
    )

    return record


# ============================================================
# SUB GROUPS
# ============================================================

async def create_sub_group(
    name: str = "گروه جدید",
    desc: str = "",
    password: str = "",
):

    name = (
        name
        or "گروه جدید"
    ).strip()[:60]

    desc = (
        desc
        or ""
    ).strip()[:200]

    password = (
        password
        or ""
    ).strip()

    sub_id = generate_uuid()

    uuid_key = secrets.token_urlsafe(16)

    record = {
        "name":
            name,

        "desc":
            desc,

        "password_hash":
            (
                hash_password(password)
                if password
                else None
            ),

        "uuid_key":
            uuid_key,

        "created_at":
            datetime.now().isoformat(),

        # Group activity is independent from the number/state of its configs.
        # A newly-created group is active by default; configs are its contents,
        # not its on/off switch.
        "active":
            True,

        "link_ids":
            [],

        # Protocol visibility rules for this subscription group.
        # Existing groups without this field remain backward-compatible (all protocols).
        "protocols": list(PROTOCOLS),
    }

    async with SUBS_LOCK:
        SUBS[sub_id] = record

    await save_state()

    log_activity(
        "sub",
        (
            f"گروه "
            f"«{name}» "
            f"ساخته شد"
        ),
        "ok",
    )

    return (
        sub_id,
        record,
    )


async def set_link_sub(
    uid: str,
    sub_id: str | None,
):

    async with LINKS_LOCK:

        if uid not in LINKS:
            return False

        old_sub = LINKS[
            uid
        ].get(
            "sub_id"
        )

        label = LINKS[
            uid
        ].get(
            "label",
            uid,
        )

    if sub_id is not None:

        async with SUBS_LOCK:

            if sub_id not in SUBS:
                return False

    async with SUBS_LOCK:

        if (
            old_sub
            and old_sub in SUBS
        ):

            ids = SUBS[
                old_sub
            ].get(
                "link_ids",
                [],
            )

            if uid in ids:
                ids.remove(uid)

        if (
            sub_id
            and sub_id in SUBS
        ):

            ids = SUBS[
                sub_id
            ].setdefault(
                "link_ids",
                [],
            )

            if uid not in ids:
                ids.append(uid)

    async with LINKS_LOCK:

        if uid in LINKS:

            LINKS[
                uid
            ][
                "sub_id"
            ] = sub_id

    await save_state()

    log_activity(
        "link",
        (
            f"کانفیگ "
            f"«{label}» "
            f"{'به گروه اضافه شد' if sub_id else 'از گروه خارج شد'}"
        ),
        "info",
    )

    return True


async def remove_sub_group(
    sub_id: str,
):

    async with SUBS_LOCK:

        if sub_id not in SUBS:
            return None

        name = SUBS[
            sub_id
        ].get(
            "name",
            sub_id,
        )

        del SUBS[sub_id]

    async with LINKS_LOCK:

        for link in LINKS.values():

            if (
                link.get("sub_id")
                == sub_id
            ):
                link["sub_id"] = None

    await save_state()

    log_activity(
        "sub",
        (
            f"گروه "
            f"«{name}» "
            f"حذف شد"
        ),
        "warn",
    )

    return name


# ============================================================
# STARTUP
# ============================================================

@app.on_event("startup")
async def startup():

    global http_client
    try:
        from onex.integrations import sell as _sell_boot
        _sell_boot.start_background()
    except Exception as _sell_exc:
        logger.warning("sell background not started: %s", _sell_exc)

    limits = httpx.Limits(
        max_connections=500,
        max_keepalive_connections=100,
    )

    timeout = httpx.Timeout(
        30.0,
        connect=10.0,
    )

    http_client = httpx.AsyncClient(
        limits=limits,
        timeout=timeout,
        follow_redirects=True,
    )

    await load_state()
    await save_state()

    await ensure_default_categories()
    await remove_legacy_default_links()

    log_activity(
        "system",
        (
            f"{APP_NAME} "
            f"v{APP_VERSION} "
            f"راه‌اندازی شد"
        ),
        "ok",
    )

    logger.info(
        "%s v%s started on 0.0.0.0:%s",
        APP_NAME,
        APP_VERSION,
        PORT,
    )

    logger.info(
        "Data directory: %s",
        DATA_DIR,
    )


@app.on_event("shutdown")
async def shutdown():

    await save_state()

    if http_client:
        await http_client.aclose()


