    AD_BLOCKER["domains"] = domains
    await save_state()
    if NATIVE_CORE:
        asyncio.create_task(sync_native_core())
    if SIDERAIL_CORE:
        asyncio.create_task(sync_siderail_core())
    return {"ok": True, **AD_BLOCKER}


