@app.patch("/api/links/{uid}")
async def update_link(
    uid: str,
    request: Request,
    _=Depends(require_auth),
):

    try:
        body = await request.json()
    except Exception:
        raise HTTPException(
            status_code=400,
            detail="اطلاعات نامعتبر است",
        )

    if not isinstance(body, dict):
        raise HTTPException(
            status_code=400,
            detail="اطلاعات نامعتبر است",
        )

    async with LINKS_LOCK:

        if uid not in LINKS:
            raise HTTPException(
                status_code=404,
                detail="link not found",
            )

        link = LINKS[uid]
        previous_link = deepcopy(link)

        old_sub = link.get(
            "sub_id"
        )

        label = link.get(
            "label",
            uid,
        )

        if "ad_block_enabled" in body:
            link["ad_block_enabled"] = bool(body.get("ad_block_enabled"))

        if "cdn_optimizer" in body:
            link["cdn_optimizer"] = bool(body.get("cdn_optimizer"))
        if "cdn_ech" in body:
            link["cdn_ech"] = normalize_cdn_ech(body.get("cdn_ech"))
        if "clean_ips" in body:
            link["clean_ips"] = [str(x).strip()[:64] for x in (body.get("clean_ips") or []) if str(x).strip()][:500]
        if "ip_proto_pairs" in body:
            pairs_in = []
            for item in (body.get("ip_proto_pairs") or [])[:500]:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    ip_v, pr_v = str(item[0]).strip()[:64], str(item[1])
                    if pr_v in PROTOCOLS:
                        pairs_in.append([ip_v, pr_v])
            link["ip_proto_pairs"] = pairs_in

        if "bundle_protocols" in body:
            raw_bundle = body.get("bundle_protocols") or []
            if not isinstance(raw_bundle, list):
                raw_bundle = []
            link["bundle_protocols"] = [str(p) for p in raw_bundle if str(p) in BUNDLE_PROTOCOLS]

        if "active" in body:
            link["active"] = bool(
                body["active"]
            )

        if "category_id" in body:
            cid = str(body.get("category_id") or "0")
            if cid not in CATEGORIES:
                cid = "0"
            link["category_id"] = cid

        if "sort_order" in body:
            try:
                link["sort_order"] = int(body.get("sort_order") or 0)
            except Exception:
                pass

        if "label" in body:

            value = str(
                body["label"]
            ).strip()

            if value:
                link["label"] = value[:60]

        if "note" in body:

            link["note"] = str(
                body.get(
                    "note",
                    "",
                )
            )[:500]

        if "reset_usage" in body:

            if body.get(
                "reset_usage"
            ):
                link[
                    "used_bytes"
                ] = 0


        if "limit_value" in body:

            value = safe_float(
                body.get(
                    "limit_value",
                    0,
                )
            )

            unit = str(
                body.get(
                    "limit_unit",
                    "GB",
                )
                or "GB"
            )

            link[
                "limit_bytes"
            ] = (
                0
                if value <= 0
                else parse_size_to_bytes(
                    value,
                    unit,
                )
            )

        if "expires_at" in body:
            raw_exp = body.get("expires_at")
            link["expires_at"] = str(raw_exp).strip()[:80] if raw_exp else None
        elif "expires_days" in body:

            days = safe_int(
                body.get(
                    "expires_days",
                    0,
                ),
                minimum=0,
            )

            link[
                "expires_at"
            ] = (
                (
                    datetime.now()
                    + timedelta(
                        days=days
                    )
                ).isoformat()
                if days > 0
                else None
            )

        if "fingerprint" in body:

            fingerprint = str(
                body.get(
                    "fingerprint",
                    DEFAULT_FINGERPRINT,
                )
            ).strip().lower()

            link[
                "fingerprint"
            ] = (
                fingerprint
                if fingerprint in FINGERPRINTS
                else DEFAULT_FINGERPRINT
            )

        if "alpn" in body:

            link["alpn"] = str(
                body.get(
                    "alpn",
                    "",
                )
            )[:100]

        if "port" in body:

            p = safe_int(
                body.get(
                    "port",
                    DEFAULT_PORT,
                ),
                default=DEFAULT_PORT,
                minimum=MIN_PORT,
                maximum=MAX_PORT,
            )

            link["port"] = p

        if "ip_limit" in body:

            link["ip_limit"] = safe_int(
                body.get(
                    "ip_limit",
                    0,
                ),
                minimum=0,
            )

        if "connection_limit" in body:

            link[
                "connection_limit"
            ] = safe_int(
                body.get(
                    "connection_limit",
                    0,
                ),
                minimum=0,
            )

        if "speed_limit_value" in body:

            speed_value = safe_float(
                body.get(
                    "speed_limit_value",
                    0,
                )
            )

            speed_unit = str(
                body.get(
                    "speed_limit_unit",
                    "MBIT",
                )
                or "MBIT"
            )

            link[
                "speed_limit_bytes"
            ] = (
                0
                if speed_value <= 0
                else parse_speed_to_bytes(
                    speed_value,
                    speed_unit,
                )
            )

        if "protocol" in body:

            protocol = str(
                body.get(
                    "protocol",
                    DEFAULT_PROTOCOL,
                )
            ).strip()

            link["protocol"] = (
                protocol
                if protocol in PROTOCOLS
                else DEFAULT_PROTOCOL
            )
            link["protocol_label"] = PROTOCOL_LABELS.get(link["protocol"], link["protocol"])

        if "config_count" in body:
            link["config_count"] = safe_int(
                body.get("config_count", 1),
                default=1,
                minimum=1,
                maximum=40,
            )

        if "all_protocols" in body:
            link["all_protocols"] = bool(body.get("all_protocols")) and link.get("protocol") in RAILWAY_SUB_PROTOCOLS
            if link["all_protocols"]:
                link["config_count"] = 1
                link["bundle_protocols"] = all_protocol_members()

        if "fragment" in body:

            fragment = str(
                body.get(
                    "fragment",
                    "off",
                )
                or "off"
            ).strip().lower()

            if fragment not in {
                "off",
                "safe",
                "balanced",
                "aggressive",
            }:
                fragment = "off"

            link["fragment"] = fragment

        if "sub_id" in body:

            link[
                "sub_id"
            ] = (
                body.get(
                    "sub_id"
                )
                or None
            )

        if "advanced" in body:
            link["advanced"] = normalize_advanced_config(body.get("advanced"))
            adv = link["advanced"]
            if adv["fingerprint"]["value"] in FINGERPRINTS:
                link["fingerprint"] = adv["fingerprint"]["value"]
            if adv.get("ports") and not link.get("all_protocols"):
                link["port"] = adv["ports"][0]
            if adv["tls"].get("alpn"):
                link["alpn"] = adv["tls"]["alpn"]

        new_sub = body.get(
            "sub_id",
            "UNCHANGED",
        )

    if new_sub != "UNCHANGED":

        async with SUBS_LOCK:

            if (
                old_sub
                and old_sub in SUBS
            ):

                ids = SUBS[
                    old_sub
                ].get(
                    "link_ids",
                    [],
                )

                if uid in ids:
                    ids.remove(uid)

            if (
                new_sub
                and new_sub in SUBS
            ):

                ids = SUBS[
                    new_sub
                ].setdefault(
                    "link_ids",
                    [],
                )

                if uid not in ids:
                    ids.append(uid)

    await save_state()

    native_relevant = bool(NATIVE_CORE and (not link.get("all_protocols")) and link.get("protocol") in getattr(NATIVE_CORE, "SUPPORTED", ()))
    if native_relevant and not await sync_native_core():
        async with LINKS_LOCK:
            LINKS[uid] = previous_link
        await save_state()
        raise HTTPException(409, NATIVE_CORE.last_error or "Native listener deployment failed; previous configuration restored")
    elif NATIVE_CORE:
        asyncio.create_task(sync_native_core())

    log_activity(
        "link",
        (
            f"کانفیگ "
            f"«{label}» "
            f"ویرایش شد"
        ),
        "info",
    )

    return {
        "ok": True
    }


