# ============================================================

@app.post(
    "/api/links/{uid}/reset-usage"
)
async def reset_link_usage(
    uid: str,
    _=Depends(require_auth),
):

    async with LINKS_LOCK:

        link = LINKS.get(uid)

        if not link:
            raise HTTPException(
                status_code=404,
                detail="link not found",
            )

        link["used_bytes"] = 0

        label = link.get(
            "label",
            uid,
        )

    await save_state()

    log_activity(
        "link",
        (
            f"مصرف کانفیگ "
            f"«{label}» ریست شد"
        ),
        "info",
    )

    return {
        "ok": True,
        "uuid": uid,
        "used_bytes": 0,
    }


# ============================================================
# LINK ACTION
# ============================================================

@app.post(
    "/api/links/{uid}/action"
)
async def link_action(
    uid: str,
    request: Request,
    _=Depends(require_auth),
):

    try:
        body = await request.json()
    except Exception:
        raise HTTPException(
            status_code=400,
            detail="JSON نامعتبر است",
        )

    action = str(
        body.get(
            "action",
            "",
        )
    ).strip().lower()

    if action == "reset":

        await reset_link_usage(
            uid,
            _
        )

        return {
            "ok": True,
            "action": "reset",
        }

    if action == "enable":

        result = await set_link_active(
            uid,
            True,
        )

        if result is None:
            raise HTTPException(
                status_code=404,
                detail="link not found",
            )

        return {
            "ok": True,
            "action": "enable",
        }

    if action == "disable":

        result = await set_link_active(
            uid,
            False,
        )

        if result is None:
            raise HTTPException(
                status_code=404,
                detail="link not found",
            )

        return {
            "ok": True,
            "action": "disable",
        }

    raise HTTPException(
        status_code=400,
        detail="unknown action",
    )


# ============================================================
# DELETE LINK
# ============================================================

@app.delete("/api/links/{uid}")
async def delete_link(
    uid: str,
    _=Depends(require_auth),
):

    async with LINKS_LOCK:
        previous = deepcopy(LINKS.get(uid)) if uid in LINKS else None
    async with SUBS_LOCK:
        previous_subs = deepcopy(SUBS)
    if previous is None:
        raise HTTPException(status_code=404, detail="link not found")
    label = await remove_link(uid)
    if NATIVE_CORE and not await sync_native_core():
        async with LINKS_LOCK:
            LINKS[uid] = previous
        async with SUBS_LOCK:
            SUBS.clear(); SUBS.update(previous_subs)
        await save_state()
        raise HTTPException(409, NATIVE_CORE.last_error or "Native runtime reload failed; previous state restored")

    return {
        "ok": True,
        "deleted": uid,
    }




def subscription_metadata_headers(used_bytes: int, limit_bytes: int, expires_at, host: str, info_url: str, title: str):
    """Standard subscription headers understood by v2rayNG/v2rayN/Hiddify and similar clients."""
    used_bytes = max(0, int(used_bytes or 0))
    limit_bytes = max(0, int(limit_bytes or 0))

    expire_unix = 0
    if expires_at:
        try:
            dt = datetime.fromisoformat(str(expires_at))
            # expires_at is written with naive datetime.now() (server local time),
            # so .timestamp() on the naive value is the exact moment.
            expire_unix = max(0, int(dt.timestamp()))
        except Exception:
            expire_unix = 0

    userinfo = f"upload=0; download={used_bytes}; total={limit_bytes}; expire={expire_unix}"

    return {
        "profile-title": quote(title, safe=""),
        "profile-web-page-url": info_url,
        "support-url": SUPPORT_URL,
        "profile-update-interval": "12",
        "subscription-userinfo": userinfo,
        "content-disposition": 'inline; filename="subscription.txt"',
    }

# ============================================================
# SINGLE SUB
# ============================================================

_SUB_CLIENT_MARKERS = (
    "v2ray", "xray", "sing-box", "singbox", "clash", "mihomo", "stash", "hiddify",
    "nekobox", "nekoray", "streisand", "shadowrocket", "quantumult", "surge", "loon",
    "foxray", "v2box", "happ", "karing", "okhttp", "dart", "flclash", "throne",
)


def request_is_browser(request: Request) -> bool:
    """True only for a normal web browser; every VPN client gets raw base64."""
    qp = request.query_params
    if qp.get("raw") or qp.get("format") in ("raw", "base64", "b64"):
        return False
    ua = (request.headers.get("user-agent") or "").lower()
    accept = (request.headers.get("accept") or "").lower()
    if not ua or any(m in ua for m in _SUB_CLIENT_MARKERS):
        return False
    return "mozilla" in ua and "text/html" in accept


# ============================================================
# EDGE GROUP SUB: one subscription for every Cloudflare Edge config
# ============================================================

def _edge_group_uris(entries, host):
    from onex.integrations import cf_edge as _cf
    out = []
    for uid, link in entries:
        try:
            base = link_config_uris(link, uid, host)
        except Exception:
            base = [vless_link_for_link(link, uid, host)]
        if link.get("ip_proto_pairs"):
            edge = _cf.edge_variants_own(base)
        else:
            edge = _cf.edge_variants(base, list(link.get("clean_ips") or []) or None)
        out.extend(edge or base)
    return out


async def _edge_group_payload(request: Request):
    from onex.integrations import cf_edge as _cf
    host = get_host(request)
    ids = _cf.edge_uids()
    async with LINKS_LOCK:
        entries = [
            (uid, dict(link)) for uid, link in LINKS.items()
            if (uid in ids or str(link.get("uuid") or "") in ids) and is_link_allowed(link)
        ]
    uris = _edge_group_uris(entries, host)
    used = sum(int(l.get("used_bytes", 0) or 0) for _, l in entries)
    limits = [int(l.get("limit_bytes", 0) or 0) for _, l in entries]
    limit = sum(limits) if entries and all(x > 0 for x in limits) else 0
    exps = [str(l.get("expires_at")) for _, l in entries if l.get("expires_at")]
    expires = min(exps) if entries and len(exps) == len(entries) else None
    snapshot = {
        "label": "ساب Edge", "used_bytes": used, "limit_bytes": limit, "expires_at": expires,
        "active": bool(entries), "protocol": "vless-ws", "fingerprint": "chrome", "usage_history": [],
    }
    token = _cf.get_sub_token()
    return host, snapshot, uris, token


@app.get("/sub/edge/{token}")
async def edge_group_sub(token: str, request: Request, format: str = ""):
    from onex.integrations import cf_edge as _cf
    if not _cf.valid_sub_token(token):
        raise HTTPException(status_code=404, detail="not found")
    host, snapshot, uris, _ = await _edge_group_payload(request)
    sub_url = f"https://{host}/sub/edge/{token}"
    if str(format).lower() == "plain":
        return Response(content="\n".join(uris) + "\n", media_type="text/plain; charset=utf-8")
    if request_is_browser(request):
        return await render_info_page("edge", snapshot, uris, sub_url, host)
    lines = subscription_info_lines("edge", snapshot) + uris
    content = base64.b64encode("\n".join(lines).encode()).decode()
    vol, tm = subscription_usage_texts(snapshot)
    headers = subscription_metadata_headers(
        snapshot["used_bytes"], snapshot["limit_bytes"], snapshot["expires_at"], host,
        sub_url, f"ساب Edge | {vol} | {tm}",
    )
    return Response(content=content, media_type="text/plain; charset=utf-8", headers=headers)


@app.get("/info/edge/{token}", response_class=HTMLResponse)
async def edge_group_info(token: str, request: Request):
    from onex.integrations import cf_edge as _cf
    if not _cf.valid_sub_token(token):
        raise HTTPException(status_code=404, detail="not found")
    host, snapshot, uris, _ = await _edge_group_payload(request)
    return await render_info_page("edge", snapshot, uris, f"https://{host}/sub/edge/{token}", host)


@app.get("/sub/{uuid}")
async def subscription_single(
    uuid: str,
    request: Request,
):

    async with LINKS_LOCK:
        link = LINKS.get(uuid)

    if not is_link_allowed(link):
        raise HTTPException(
            status_code=404,
            detail="not found or inactive",
        )

    host = get_host(request)
    clean_ips = link.get("clean_ips") or []
    used = int(link.get("used_bytes", 0) or 0)
    limit = int(link.get("limit_bytes", 0) or 0)
    remaining = max(0, limit - used) if limit > 0 else 0
    volume_text = f"{fmt_bytes(used)}/{fmt_bytes(limit)} (باقی {fmt_bytes(remaining)})" if limit > 0 else f"{fmt_bytes(used)}/∞"
    expires_at = link.get("expires_at")
    if expires_at:
        try:
            exp_dt = datetime.fromisoformat(str(expires_at))
            now_dt = datetime.now(exp_dt.tzinfo) if getattr(exp_dt, "tzinfo", None) else datetime.now()
            secs = int((exp_dt - now_dt).total_seconds())
            if secs <= 0:
                time_text = "منقضی"
            else:
                days, rem = divmod(secs, 86400)
                hours, rem = divmod(rem, 3600)
                mins = rem // 60
                time_text = f"{days}د {hours}س" if days else (f"{hours}س {mins}د" if hours else f"{mins}د")
        except Exception:
            time_text = str(expires_at)[:16]
    else:
        time_text = "∞"
    label = str(link.get("label") or "Config")
    stats_remark = f"{label} | {volume_text} | {time_text}"
    # A real browser (not a VPN client) gets the readable subscription page that
    # lists every config of this sub.  VPN clients keep receiving base64.
    if request_is_browser(request):
        return await info_page(uuid, request)
    # 1) usage info (remaining volume + remaining time) with icons, always first
    lines = subscription_info_lines(uuid, link)
    # 2) every config of this sub (all selected protocols, all clean IPs)
    _uris = link_config_uris(link, uuid, host)
    # Edge variants only go to the dedicated Edge subscription, never to every sub
    try:
        from onex.integrations.cf_edge import is_edge_only, edge_only_uris as _edge_only, edge_variants_own as _edge_own
        if is_edge_only(uuid, link.get("uuid")):
            _edge_lines = _edge_own(_uris) if link.get("ip_proto_pairs") else _edge_only(_uris)
            lines.extend(_edge_lines or _uris)
        else:
            lines.extend(_uris)
    except Exception as _edge_exc:
        logger.debug("edge sub skipped: %s", _edge_exc)
        lines.extend(_uris)
    content = base64.b64encode("\n".join(lines).encode()).decode()
    _vol_t, _time_t = subscription_usage_texts(link)
    profile_title = f"{label} | {_vol_t} | {_time_t}"
    headers = subscription_metadata_headers(
        used,
        limit,
        link.get("expires_at"),
        host,
        f"https://{host}/info/{uuid}",
        profile_title,
    )

    return Response(
        content=content,
        media_type="text/plain; charset=utf-8",
        headers=headers,
    )

