# ============================================================
# HTTP PROXY
# ============================================================

_HOP = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailers",
    "transfer-encoding",
    "upgrade",
    "content-encoding",
    "content-length",
}


@app.api_route(
    "/proxy/{target_url:path}",
    methods=[
        "GET",
        "POST",
        "PUT",
        "DELETE",
        "PATCH",
        "HEAD",
        "OPTIONS",
    ],
)
async def http_proxy(
    target_url: str,
    request: Request,
):

    if not target_url.startswith("http"):
        target_url = (
            "https://"
            + target_url
        )

    if http_client is None:
        raise HTTPException(
            status_code=503,
            detail="HTTP client not ready",
        )

    try:

        body = await request.body()

        headers = {
            key: value
            for key, value
            in request.headers.items()
            if (
                key.lower()
                not in _HOP
            )
            and (
                key.lower()
                != "host"
            )
        }

        request_size = len(body or b"")
        stats["upload_bytes"] = stats.get("upload_bytes", 0) + request_size
        hour_key = now_ir().strftime("%H:00")
        hourly_upload[hour_key] += request_size

        response = await http_client.request(
            method=request.method,
            url=target_url,
            headers=headers,
            content=body,
        )

        response_size = len(response.content)
        stats["total_bytes"] += response_size
        stats["download_bytes"] = stats.get("download_bytes", 0) + response_size

        stats["total_requests"] += 1

        hourly_traffic[hour_key] += response_size

        output_headers = {
            key: value
            for key, value
            in response.headers.items()
            if key.lower() not in _HOP
        }

        return Response(
            content=response.content,
            status_code=response.status_code,
            headers=output_headers,
        )

    except Exception as exc:

        stats["total_errors"] += 1

        error_logs.append(
            {
                "error":
                    str(exc),

                "url":
                    target_url,

                "time":
                    datetime.now().isoformat(),
            }
        )

        logger.exception(
            "Proxy error: %s",
            target_url,
        )

        raise HTTPException(
            status_code=502,
            detail=(
                "Proxy error: "
                f"{exc}"
            ),
        )


# ============================================================
# DASHBOARD
# ============================================================

# ============================================================
# SYSTEM METRICS (dashboard home: CPU / RAM / Disk / Network)
# stdlib only — safe fallbacks on non-Linux hosts
# ============================================================

def _sysm_read_cpu():
    with open("/proc/stat", "r", encoding="utf-8") as fh:
        vals = [int(v) for v in fh.readline().split()[1:]]
    idle = vals[3] + (vals[4] if len(vals) > 4 else 0)
    return idle, sum(vals)


def _sysm_read_net():
    rx = tx = 0
    with open("/proc/net/dev", "r", encoding="utf-8") as fh:
        for line in fh.readlines()[2:]:
            if ":" not in line:
                continue
            name, data = line.split(":", 1)
            if name.strip() == "lo":
                continue
            cols = data.split()
            rx += int(cols[0])
            tx += int(cols[8])
    return rx, tx


def _sysm_read_mem():
    total = used = None
    # Containers (Railway/Docker): prefer the cgroup limit when one is set.
    try:
        raw_max = Path("/sys/fs/cgroup/memory.max").read_text().strip()
        raw_cur = Path("/sys/fs/cgroup/memory.current").read_text().strip()
        if raw_max.isdigit() and raw_cur.isdigit():
            total, used = int(raw_max), int(raw_cur)
    except Exception:
        pass
    if total is None:
        info = {}
        with open("/proc/meminfo", "r", encoding="utf-8") as fh:
            for line in fh:
                key, _, rest = line.partition(":")
                info[key] = int(rest.strip().split()[0]) * 1024
        total = info.get("MemTotal") or 0
        used = total - info.get("MemAvailable", info.get("MemFree", 0))
    return total, used


@app.get("/api/system/metrics")
async def api_system_metrics(_=Depends(require_auth)):
    import platform
    import shutil

    out = {
        "ok": True,
        "cpu_percent": None,
        "mem_percent": None,
        "disk_percent": None,
        "net_rx_rate": None,
        "net_tx_rate": None,
        "platform": f"{platform.system()} {platform.release()}".strip(),
        "python": platform.python_version(),
        "region": os.getenv("RAILWAY_REPLICA_REGION") or os.getenv("RAILWAY_REGION") or os.getenv("ONEX_REGION") or None,
        "public_domain": os.getenv("RAILWAY_PUBLIC_DOMAIN") or None,
        "singbox_version": None,
        "native_running": None,
    }
    try:
        from onex.core.native_core import VERSION as _SB_VERSION
        out["singbox_version"] = _SB_VERSION
    except Exception:
        pass
    try:
        if NATIVE_CORE:
            out["native_running"] = bool(NATIVE_CORE.status().get("running"))
    except Exception:
        pass

    cpu1 = net1 = None
    try:
        cpu1 = _sysm_read_cpu()
    except Exception:
        pass
    try:
        net1 = _sysm_read_net()
    except Exception:
        pass
    t1 = time.monotonic()
    if cpu1 or net1:
        await asyncio.sleep(0.25)
    dt = max(time.monotonic() - t1, 1e-3)
    try:
        if cpu1:
            idle2, total2 = _sysm_read_cpu()
            d_total = max(total2 - cpu1[1], 1)
            out["cpu_percent"] = round(100.0 * (1 - (idle2 - cpu1[0]) / d_total), 1)
    except Exception:
        pass
    try:
        if net1:
            rx2, tx2 = _sysm_read_net()
            out["net_rx_rate"] = max(0, round((rx2 - net1[0]) / dt))
            out["net_tx_rate"] = max(0, round((tx2 - net1[1]) / dt))
            out["net_rx_total"], out["net_tx_total"] = rx2, tx2
    except Exception:
        pass
    try:
        total, used = _sysm_read_mem()
        if total:
            out["mem_total_bytes"], out["mem_used_bytes"] = total, used
            out["mem_percent"] = round(100.0 * used / total, 1)
    except Exception:
        pass
    try:
        du = shutil.disk_usage(str(DATA_DIR))
        out["disk_total_bytes"], out["disk_used_bytes"] = du.total, du.used
        out["disk_percent"] = round(100.0 * du.used / max(du.total, 1), 1)
    except Exception:
        pass
    return out


